#include <stdint.h>
#include "stm32f7xx.h"

#if !defined(__SOFT_FP__) && defined(__ARM_FP)
  #warning "FPU is not initialized, but the project is compiling for an FPU. Please initialize the FPU before use."
#endif

const uint32_t colors[6] = {
	(1UL << 9), // red
	(1UL << 9) | (1UL << 8), // yellow
	(1UL << 8), // green
	(1UL << 8) | (1UL << 7), // cyan
	(1UL << 7), // blue
	(1UL << 9) | (1UL << 7) // magenta
};

void simpleDelay(uint32_t count) {
	while (count--) {
		__asm__("NOP");
	}
}


int main(void) {



	// Enable GPIOF clock
	RCC->AHB1ENR |= (1UL << 5);

	// Clear MODER for pins 6-9
	GPIOF->MODER &= ~(0xFFUL << (6 * 2));

	// Set PF7-PF9 as general-purpose outputs
	GPIOF->MODER |= (0x15UL << (7 * 2));

	// Set PF6-PF9 as push-pull
	GPIOF->OTYPER &= ~(0xFUL << 6);

	// Configure PF6 with pull-up
	GPIOF->PUPDR &= ~(0x3UL << (6 * 2));
	GPIOF->PUPDR |= (0b01UL << (6 * 2));

	uint8_t i = 0;
	uint8_t previous = 0;
	uint8_t led_on = 0;


	while(1) {

		uint8_t pressed = !((1UL<<6) & GPIOF->IDR);

		if ((previous ^ pressed) && pressed ) {
			led_on ^= 1;
		}

	    previous = pressed;




		if(led_on) {
			GPIOF->ODR = (GPIOF->ODR & ~(7UL << 7)) | colors[i]; //show colour i
			i = (i + 1) % 6; // next colour
			simpleDelay(1000000); // how long each colour lasts
		} else {
			GPIOF->ODR &= ~(7UL << 7);
		}

	}

	return 0;
}
